const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
let csrf='',me=null,currentView='dashboard',cache={},shareMonth=new Date().toISOString().slice(0,7),listStates={};
const labels={dashboard:['经营控制台 / 总览','经营总览'],customers:['销售前台 / CRM','客户与跟进'],quotes:['销售前台 / PI','报价管理'],orders:['销售前台 / SO','销售合同'],products:['供应与履约 / 主数据','产品中心'],suppliers:['供应与履约 / 主数据','供应商'],purchases:['供应与履约 / PO','采购管理'],deliveries:['供应与履约 / DO','出运管理'],afterSales:['供应与履约 / AS','售后与客诉'],finance:['经营控制 / 资金','应收应付'],shares:['经营控制 / 利润','利润与提成'],approvals:['经营控制 / 工作流','审批中心'],notifications:['经营控制 / 消息','通知中心'],audit:['经营控制 / 合规','审计日志'],settings:['经营控制 / 管理','系统设置']};
const statusMap={draft:'草稿',new:'新线索',contacted:'已联系',qualified:'高意向',quoted:'已报价',sampled:'已打样',won:'已成交',effective:'已生效',in_progress:'执行中',completed:'已完成',closed:'已结案',void:'已作废',void_pending:'作废审批中',approval_pending:'审批中',pending:'待处理',waiting:'等待前序',outstanding:'待收付',partial:'部分完成',approved:'已通过',rejected:'已驳回',confirmed:'已确认',reversed:'已冲正',reversal:'冲正记录',withdrawn:'已撤回',cancelled:'已取消',booked:'已订舱',production:'生产中',ready:'待收货',received:'已收货',shipped:'已出运',arrived:'已到港',delivered:'已签收',unpaid:'未收款',paid:'已结清',active:'启用',low:'低风险',medium:'中风险',high:'高风险'};
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className=`toast show ${error?'error':''}`;setTimeout(()=>el.className='toast',2600)}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(options.method&&options.method!=='GET')headers['x-csrf-token']=csrf;const res=await fetch(path,{...options,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error((data.error||'请求失败')+(Array.isArray(data.details)?`：${data.details.slice(0,8).join('；')}`:''));return data}
const fmtMoney=(v,c='CNY')=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(v||0));
const fmtDate=v=>v?new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',year:'numeric'}).format(new Date(v)):'—';
const status=v=>`<span class="status ${v}">${statusMap[v]||v||'—'}</span>`;
const empty=(title='暂无记录',sub='创建第一条记录后，数据会显示在这里。')=>`<div class="empty"><strong>${title}</strong>${sub}</div>`;
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const attr=v=>esc(v).replace(/\n/g,' ');
function table(columns,rows){if(!rows.length)return empty();return `<div class="table-card"><div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td>${typeof c[1]==='function'?c[1](r):r[c[1]]??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function batchChoices(module){return{customers:[['set_stage:new','改为新线索'],['set_stage:contacted','改为已联系'],['set_stage:qualified','改为高意向'],['set_stage:quoted','改为已报价'],['set_stage:won','改为已成交']],products:[['set_status:active','批量启用'],['set_status:inactive','批量停用']],suppliers:[['set_status:approved','批量准入'],['set_status:pending','改为待审核'],['set_status:suspended','暂停合作']]}[module]||[]}
function smartList(module,columns,rows,fields){const views=(cache.savedViews||[]).filter(v=>v.module===module);if(!listStates[module]){const preset=views.find(v=>v.is_default);listStates[module]={filters:{...(preset?.filters||{})},page:1,pageSize:preset?.page_size||20,viewId:preset?.id||'',selected:[]}}const state=listStates[module];state.selected=state.selected||[];let filtered=rows.filter(row=>fields.every(([key])=>!state.filters[key]||String(row[key]??'').toLowerCase().includes(String(state.filters[key]).toLowerCase())));state.selected=state.selected.filter(id=>rows.some(row=>row.id===id));const pages=Math.max(1,Math.ceil(filtered.length/state.pageSize));state.page=Math.min(Math.max(1,state.page),pages);const start=(state.page-1)*state.pageSize,pageRows=filtered.slice(start,start+state.pageSize);state.visibleIds=pageRows.map(row=>row.id);const controls=`<div class="list-controls"><div class="filter-fields">${fields.map(([key,label,options])=>options?`<label>${label}<select data-list-filter="${key}" data-module="${module}"><option value="">全部</option>${options.map(([v,t])=>`<option value="${attr(v)}" ${String(state.filters[key]||'')===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`:`<label>${label}<input data-list-filter="${key}" data-module="${module}" value="${attr(state.filters[key]||'')}" placeholder="包含关键词"></label>`).join('')}</div><div class="view-tools"><select data-load-view="${module}"><option value="">保存的视图</option>${views.map(v=>`<option value="${v.id}" ${state.viewId===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><button class="secondary" data-save-view="${module}">保存当前视图</button>${state.viewId?`<button class="action-link danger" data-delete-view="${state.viewId}" data-module="${module}">删除视图</button>`:''}</div></div><div class="batch-bar"><span>已选择 <strong>${state.selected.length}</strong> 条（可跨页）</span><button class="secondary" data-batch-export="${module}" ${state.selected.length?'':'disabled'}>导出所选 CSV</button>${batchChoices(module).length?`<select data-batch-choice="${module}">${batchChoices(module).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><button class="primary" data-batch-apply="${module}" ${state.selected.length?'':'disabled'}>应用到所选</button>`:''}<button class="action-link" data-clear-selection="${module}" ${state.selected.length?'':'disabled'}>清空选择</button></div><div class="list-summary"><span>筛选结果 ${filtered.length} / ${rows.length} 条</span><div><button class="action-link" data-page="prev" data-module="${module}" ${state.page<=1?'disabled':''}>上一页</button><strong>${state.page} / ${pages}</strong><button class="action-link" data-page="next" data-module="${module}" ${state.page>=pages?'disabled':''}>下一页</button></div></div>`;const selectedAll=pageRows.length&&pageRows.every(row=>state.selected.includes(row.id));return controls+table([[`<input type="checkbox" data-select-page="${module}" ${selectedAll?'checked':''} aria-label="选择本页">`,r=>`<input type="checkbox" data-select-row="${module}" value="${r.id}" ${state.selected.includes(r.id)?'checked':''} aria-label="选择 ${esc(r.document_no||r.name)}">`],...columns],pageRows)}
function exportSelected(module){const state=listStates[module],rows=(cache[module]||[]).filter(row=>state.selected.includes(row.id));if(!rows.length)return toast('请先选择记录',true);const hidden=new Set(['id','company_id','password_hash','deleted_at']);const keys=[...new Set(rows.flatMap(row=>Object.keys(row)))].filter(key=>!hidden.has(key)&&!key.endsWith('_minor')&&rows.some(row=>typeof row[key]!=='object'));const csv=[keys.join(','),...rows.map(row=>keys.map(key=>`"${String(row[key]??'').replaceAll('"','""')}"`).join(','))].join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));link.download=`${module}-selected-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function pageHead(text,sub,action='',secondary=''){return `<div class="page-actions"><div class="left"><h3>${text}</h3><p>${sub}</p></div><div class="right">${secondary}${action}</div></div>`}
function modal(title,fields,onSubmit,kicker='CREATE RECORD'){const d=$('#modal');$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=`<div class="form-grid">${fields}</div>`;d.showModal();$('#modal-submit').onclick=async e=>{e.preventDefault();const form=new FormData(d.querySelector('form'));const data=Object.fromEntries(form.entries());try{await onSubmit(data);d.close();toast('已保存并写入审计日志');load(currentView)}catch(err){toast(err.message,true)}}}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;const source=String(text).replace(/^\uFEFF/,'');for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(rows.length<2)return[];const headers=rows[0].map(x=>x.trim());return rows.slice(1).map(values=>Object.fromEntries(headers.map((key,index)=>[key,values[index]??''])))}
const field=(name,label,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" ${extra}></label>`;
const select=(name,label,opts)=>`<label>${label}<select name="${name}">${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;

const entityMeta={customers:{key:'customer',title:'客户详情',type:'customer'},suppliers:{key:'supplier',title:'供应商详情',type:'supplier'},products:{key:'product',title:'产品详情',type:'product'},quotes:{key:'quote',title:'报价详情',type:'quote'},orders:{key:'order',title:'销售合同详情',type:'sales_order'},purchases:{key:'purchase',title:'采购单详情',type:'purchase_order'},deliveries:{key:'delivery',title:'出运单详情',type:'delivery_order'},approvals:{key:'approval',title:'审批详情',type:'approval'}};
const hideKeys=new Set(['id','company_id','created_by','owner_id','supplier_id','customer_id','quote_id','sales_order_id','password_hash','deleted_at']);
function displayKey(k){return ({document_no:'单据编号',name:'名称',country:'国家/地区',contact_name:'联系人',email:'邮箱',phone:'电话',stage:'业务阶段',level:'客户等级',owner_name:'负责人',next_action:'下一动作',next_followup_at:'下次跟进',risk_level:'风险等级',status:'状态',sku:'SKU',category:'分类',unit:'单位',moq:'MOQ',sale_price:'参考售价',cost_price:'参考成本',currency:'币种',supplier_name:'供应商',customer_name:'客户',exchange_rate:'执行汇率',incoterm:'贸易术语',payment_terms:'付款条款',valid_until:'有效期',amount:'金额',cost:'成本',margin_bps:'毛利率',version:'版本',expected_at:'预计交期',forwarder:'货代',transport_mode:'运输方式',tracking_no:'追踪号',freight:'运费',planned_at:'计划日期',shipped_at:'实际出运',created_at:'创建时间',updated_at:'更新时间',reason:'申请原因',assigned_role:'当前审批角色',requester_name:'申请人',decider_name:'最终审批人'}[k]||k.replaceAll('_',' '));}
function displayValue(k,v,row){if(v===null||v===undefined||v==='')return '—';if(k.endsWith('_at')||k==='valid_until')return fmtDate(v);if(k==='margin_bps')return `${(Number(v)/100).toFixed(2)}%`;if(['amount','cost','sale_price','cost_price','freight','unit_price','unit_cost','base_amount'].includes(k))return fmtMoney(v,row.currency||'CNY');if(k==='status'||k==='stage'||k==='risk_level')return statusMap[v]||v;return v;}
function factGrid(row){return `<div class="detail-facts">${Object.entries(row).filter(([k,v])=>!hideKeys.has(k)&&!k.endsWith('_minor')&&typeof v!=='object').map(([k,v])=>`<div><small>${esc(displayKey(k))}</small><strong>${esc(displayValue(k,v,row))}</strong></div>`).join('')}</div>`;}
function relatedSection(title,rows){if(!Array.isArray(rows)||!rows.length)return '';return `<section class="detail-section"><div class="panel-head"><h3>${esc(title)}</h3><span>${rows.length} 条</span></div><div class="related-list">${rows.map(r=>`<article>${Object.entries(r).filter(([k,v])=>!hideKeys.has(k)&&!k.endsWith('_minor')&&typeof v!=='object').slice(0,7).map(([k,v])=>`<span><small>${esc(displayKey(k))}</small>${esc(displayValue(k,v,r))}</span>`).join('')}</article>`).join('')}</div></section>`;}
function timeline(events=[]){return `<section class="detail-section"><div class="panel-head"><h3>业务轨迹</h3><span>不可篡改</span></div>${events.length?`<div class="timeline">${events.map(e=>`<div><i></i><p><strong>${esc(e.event_type)}</strong><span>${esc(e.created_by_name||'系统')} · ${fmtDate(e.created_at)}</span><em>${esc(e.note||`${e.from_status||''} → ${e.to_status||''}`)}</em></p></div>`).join('')}</div>`:empty('暂无状态事件','新的跟进、修改、审批和作废会记录在这里。')}</section>`;}
async function openDetail(entity,id){const meta=entityMeta[entity];if(!meta)return;const d=$('#detail-drawer');$('#detail-title').textContent=meta.title;$('#detail-kicker').textContent=`TRACEABLE RECORD · ${entity.toUpperCase()}`;$('#detail-body').innerHTML=empty('正在读取完整业务链…','');d.showModal();try{const [data,attachments]=await Promise.all([api(`/api/${entity}/${id}`),api(`/api/attachments?objectType=${meta.type}&objectId=${id}`)]);const main=data[meta.key];const canEdit=['customers','suppliers','products','purchases','deliveries'].includes(entity)||(entity==='quotes'&&['draft','rejected'].includes(main.status));const actions=`<div class="detail-actions">${entity==='approvals'?'':`${canEdit?`<button class="primary" data-detail-edit="${entity}">编辑资料</button>`:''}${entity==='customers'?'<button class="secondary" data-followup-detail>记录跟进</button>':''}${entity==='products'?'<button class="secondary" data-add-supplier-quote>新增供应商报价</button>':''}${entity==='orders'?'<button class="primary" data-order-status>推进状态</button>':''}${main.status==='void'?'':`<button class="danger-button" data-detail-void="${entity}">申请作废</button>`}`}<button class="secondary" data-upload-attachment>＋ 上传附件</button></div>`;const sectionNames={items:'明细行',followups:'跟进记录',quotes:'关联报价',supplierQuotes:'供应商报价',orders:'关联合同',products:'供应产品',purchases:'采购记录',deliveries:'出运记录',expenses:'费用明细',schedules:'付款计划',finance:'资金流水',afterSales:'售后记录',steps:'审批节点'};const attachmentSection=`<section class="detail-section"><div class="panel-head"><h3>单据附件</h3><span>${attachments.length} 个</span></div>${attachments.length?`<div class="attachment-list">${attachments.map(a=>`<a href="/api/attachments/${a.id}/download"><strong>${esc(a.file_name)}</strong><span>${esc(a.mime_type)} · ${(a.size_bytes/1024).toFixed(1)} KB · ${fmtDate(a.created_at)}</span><em>下载</em></a>`).join('')}</div>`:empty('暂无附件','支持 PDF、图片、文本、CSV 和 Office 文件。')}</section>`;$('#detail-body').innerHTML=actions+factGrid(main)+attachmentSection+Object.entries(data).filter(([k,v])=>k!==meta.key&&!['events','audit','approvals','profit'].includes(k)&&Array.isArray(v)).map(([k,v])=>relatedSection(sectionNames[k]||k,v)).join('')+(data.profit?relatedSection('利润快照',[data.profit]):'')+timeline(data.events||[]);d.dataset.entity=entity;d.dataset.record=JSON.stringify(main);d.dataset.payload=JSON.stringify(data);bindDetailActions();}catch(e){$('#detail-body').innerHTML=empty('无法读取详情',e.message);}}
function selected(name,label,opts,current){return `<label>${label}<select name="${name}">${opts.map(([v,t])=>`<option value="${attr(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function editField(name,label,value,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${attr(value??'')}" ${extra}></label>`;}
function openDirectOrderEditor(customers,products,order=null,items=[]){openQuoteEditor({quote:order,items,expenses:[],customers,products});$('#modal-title').textContent=order?'修改销售合同草稿':'直接新建销售合同';$('#modal-kicker').textContent=order?'REVISE SALES CONTRACT':'DIRECT SALES CONTRACT';['validUntil','extraFeeName','extraFeeAmount','costFeeName','costFeeAmount'].forEach(name=>$('#modal').querySelector(`[name="${name}"]`)?.closest('label')?.classList.add('hidden'));const notes=$('#modal').querySelector('[name="notes"]')?.closest('label');if(notes)notes.childNodes[0].textContent='合同备注';$('#modal-submit').onclick=async e=>{e.preventDefault();const d=$('#modal'),data=Object.fromEntries(new FormData(d.querySelector('form')).entries()),lines=$$('#quote-line-list .quote-line').map(line=>({productId:line.querySelector('[name=productId]').value||null,description:line.querySelector('[name=description]').value,quantity:Number(line.querySelector('[name=quantity]').value),unitPrice:Number(line.querySelector('[name=unitPrice]').value),unitCost:Number(line.querySelector('[name=unitCost]').value)}));try{await api(order?`/api/orders/${order.id}`:'/api/orders',{method:order?'PUT':'POST',body:JSON.stringify({...data,items:lines})});d.close();toast(order?'销售合同已恢复为草稿，可重新提交审批':`已建立 ${lines.length} 行销售合同草稿`);load('orders')}catch(error){toast(error.message,true)}}}
async function openFulfillmentDraftEditor(entity,record,payload){const order=await api(`/api/orders/${record.sales_order_id}`),existing=new Map((payload.items||[]).map(item=>[item.sales_order_item_id,item]));const purchase=entity==='purchases';const rows=order.items.map((item,index)=>{const current=existing.get(item.id);return `<div class="quote-line fulfillment-edit-line" data-item="${item.id}"><div class="quote-line-head"><strong>${index+1}. ${esc(item.description)}</strong><span>合同数量 ${item.quantity}</span></div>${editField('quantity','本单数量',current?.quantity||0,'number','min="0" step="0.01"')}${purchase?editField('unitCost','采购单价',current?.unit_cost??item.unit_cost??0,'number','min="0" step="0.01"'):''}<small class="full muted">填 0 表示本单不包含此产品；系统会扣除其他单据和已关闭数量后再校验。</small></div>`}).join('');const common=`${editField('version','版本',record.version,'hidden')}`;const fields=purchase?editField('orderedAt','采购日期',String(record.ordered_at||'').slice(0,10),'date')+editField('expectedAt','预计交期',String(record.expected_at||'').slice(0,10),'date')+selected('procurementMethod','采购方式',[['direct','直接采购'],['sample','打样'],['outsourcing','委外加工']],record.procurement_method||'direct')+selected('taxIncluded','含税交易',[['','不含税'],['1','含税']],record.tax_included?'1':'')+editField('taxRate','税率（%）',record.tax_rate||0,'number','min="0" step="0.01"')+editField('paymentTerms','付款节奏',record.payment_terms||'')+`<label class="full">采购备注<textarea name="notes" rows="3">${esc(record.notes||'')}</textarea></label>`:editField('forwarder','货代',record.forwarder,'text','required')+selected('transportMode','运输方式',[['sea','海运'],['air','空运'],['rail','铁路'],['express','快递']],record.transport_mode)+editField('trackingNo','追踪号',record.tracking_no||'')+editField('plannedAt','计划出运',String(record.planned_at||'').slice(0,10),'date')+editField('freight','国际运费',record.freight||0,'number','min="0" step="0.01"')+editField('originLocation','出运地点',record.origin_location||'')+selected('incoterm','贸易条款',[['FOB','FOB'],['CIF','CIF'],['EXW','EXW'],['DDP','DDP']],record.incoterm||'FOB')+editField('packageMaterials','包装物料',record.package_materials||'')+editField('packageCount','箱数',record.package_count||0,'number','min="0"')+editField('grossWeight','毛重（kg）',record.gross_weight||0,'number','min="0" step="0.01"')+editField('volumeCbm','体积（CBM）',record.volume_cbm||0,'number','min="0" step="0.001"')+`<label class="full">出运备注<textarea name="notes" rows="3">${esc(record.notes||'')}</textarea></label>`;modal(purchase?'编辑采购草稿':'编辑出运草稿',fields+`<section class="full quote-lines"><div class="panel-head"><h3>合同产品明细</h3><span>可调整、增加或移除</span></div><div id="fulfillment-edit-list">${rows}</div></section>`+common,async()=>{},purchase?'REVISE PURCHASE ORDER':'REVISE DELIVERY ORDER');const d=$('#modal');$('#modal-submit').onclick=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(d.querySelector('form')).entries()),items=$$('#fulfillment-edit-list .fulfillment-edit-line').map(line=>({salesOrderItemId:line.dataset.item,quantity:Number(line.querySelector('[name=quantity]').value),...(purchase?{unitCost:Number(line.querySelector('[name=unitCost]').value)}:{})})).filter(item=>item.quantity>0);try{if(!items.length)throw new Error('单据至少保留一行数量大于 0 的产品');await api(`/api/${entity}/${record.id}`,{method:'PUT',body:JSON.stringify({...data,taxIncluded:Boolean(data.taxIncluded),items})});d.close();toast('草稿明细已更新，可重新提交审批');load(entity)}catch(error){toast(error.message,true)}}}
function openReallocationEditor(workbench,users){const rejected=workbench.shares.filter(share=>share.status==='rejected'),d=$('#modal');const rows=rejected.map(share=>`<div class="quote-line reallocation-line" data-share="${share.id}"><div class="quote-line-head"><label><input type="checkbox" name="include" checked> ${esc(share.document_no)} · ${esc(share.sales_order_no)}</label><span>原 ${esc(share.beneficiary_name)} · ${fmtMoney(share.amount_base)}</span></div>${selected('beneficiaryId','新分配人员',users.map(u=>[u.id,`${u.name} · ${statusMap[u.role]||u.role}`]),share.beneficiary_id)}${editField('amount','新分配金额（CNY）',share.amount_base,'number','min="0.01" step="0.01" required')}</div>`).join('');modal('原方案批量重分配',`<div class="full schedule-summary"><strong>${workbench.month} · ${rejected.length} 条被驳回记录</strong><p>先预览人员、金额和比例差异；确认后整批提交运营、财务审批。</p></div><section class="full quote-lines"><div id="reallocation-list">${rows}</div></section><label class="full">重分配说明<textarea name="notes" rows="3" minlength="4" required></textarea></label>`,async()=>{},'MONTHLY REALLOCATION');$('#modal-submit').textContent='预览差异';$('#modal-submit').onclick=async e=>{e.preventDefault();const notes=d.querySelector('[name=notes]').value,allocations=$$('#reallocation-list .reallocation-line').filter(line=>line.querySelector('[name=include]').checked).map(line=>({shareId:line.dataset.share,beneficiaryId:line.querySelector('[name=beneficiaryId]').value,amount:Number(line.querySelector('[name=amount]').value)}));try{const preview=await api('/api/performance/reallocation/preview',{method:'POST',body:JSON.stringify({month:workbench.month,allocations})});$('#modal-title').textContent='确认重分配差异';$('#modal-body').innerHTML=`<div class="form-grid"><div class="full schedule-summary"><strong>原合计 ${fmtMoney(preview.summary.oldTotal)} → 新合计 ${fmtMoney(preview.summary.newTotal)}</strong><p>差额 ${fmtMoney(preview.summary.delta)} · ${preview.summary.contractCount} 份合同 · ${preview.summary.peopleBefore} 人 → ${preview.summary.peopleAfter} 人</p></div><div class="full">${table([['分成单','documentNo'],['合同','salesOrderNo'],['原人员','oldBeneficiaryName'],['新人员','newBeneficiaryName'],['原金额',r=>fmtMoney(r.oldAmountMinor/100)],['新金额',r=>fmtMoney(r.newAmountMinor/100)],['差额',r=>fmtMoney(r.deltaMinor/100)],['新比例',r=>`${(r.newAllocationBps/100).toFixed(2)}%`]],preview.changes)}</div></div>`;$('#modal-submit').textContent='确认并提交审批';$('#modal-submit').onclick=async event=>{event.preventDefault();try{await api('/api/performance/reallocations',{method:'POST',body:JSON.stringify({month:workbench.month,allocations,notes})});d.close();toast('月度重分配方案已提交运营、财务审批');load('shares')}catch(error){toast(error.message,true)}}}catch(error){toast(error.message,true)}}}
function quoteLine(products,item={},index=0){const opts=[['','自定义产品'],...products.map(p=>[p.id,`${p.sku} · ${p.name}`])];return `<div class="quote-line"><div class="quote-line-head"><strong>产品明细 ${index+1}</strong><button type="button" class="action-link danger" data-remove-quote-line>删除</button></div>${selected('productId','产品',opts,item.product_id||item.productId||'')}${editField('description','产品描述',item.description||'','text','required')}${editField('quantity','数量',item.quantity||100,'number','min="0.01" step="0.01" required')}${editField('unitPrice','销售单价',item.unit_price??item.unitPrice??10,'number','min="0" step="0.01" required')}${editField('unitCost','单位成本',item.unit_cost??item.unitCost??7,'number','min="0" step="0.01" required')}</div>`}
function openQuoteEditor({quote=null,items=[],expenses=[],customers,products}){const d=$('#modal');const revenue=expenses.find(x=>x.category==='revenue'),cost=expenses.find(x=>x.category==='cost');$('#modal-title').textContent=quote?'修订报价':'创建多产品报价';$('#modal-kicker').textContent=quote?'REVISE QUOTATION':'MULTI-LINE PROFORMA INVOICE';$('#modal-body').innerHTML=`<div class="form-grid">${selected('customerId','客户',customers.map(c=>[c.id,c.name]),quote?.customer_id||customers[0]?.id)}${selected('currency','币种',[['USD','USD'],['CNY','CNY'],['EUR','EUR'],['HKD','HKD'],['GBP','GBP']],quote?.currency||'USD')}${editField('exchangeRate','执行汇率',quote?.exchange_rate||7.2,'number','min="0.000001" step="0.000001" required')}${selected('incoterm','贸易术语',[['FOB','FOB'],['CIF','CIF'],['EXW','EXW'],['DDP','DDP']],quote?.incoterm||'FOB')}${editField('paymentTerms','付款条款',quote?.payment_terms||'30% deposit, 70% before shipment')}${editField('deliveryAt','预计交期',String(quote?.delivery_at||'').slice(0,10),'date')}${editField('validUntil','有效期至',String(quote?.valid_until||new Date(Date.now()+30*86400000).toISOString()).slice(0,10),'date','required')}${editField('extraFeeName','额外费用名称',revenue?.name||'')}${editField('extraFeeAmount','额外费用金额',revenue?.amount||0,'number','min="0" step="0.01"')}${editField('costFeeName','预估成本名称',cost?.name||'')}${editField('costFeeAmount','预估成本金额',cost?.amount||0,'number','min="0" step="0.01"')}<label class="full">报价备注<textarea name="notes" rows="3">${esc(quote?.notes||'')}</textarea></label><section class="full quote-lines"><div class="panel-head"><h3>产品明细</h3><button type="button" class="secondary" id="add-quote-line">＋ 添加产品行</button></div><div id="quote-line-list">${(items.length?items:[{}]).map((item,i)=>quoteLine(products,item,i)).join('')}</div></section>${quote?`<input type="hidden" name="version" value="${quote.version}">`:''}</div>`;d.showModal();const renumber=()=>{$$('#quote-line-list .quote-line').forEach((line,i)=>line.querySelector('.quote-line-head strong').textContent=`产品明细 ${i+1}`);$$('[data-remove-quote-line]').forEach(b=>b.onclick=()=>{if($$('#quote-line-list .quote-line').length===1)return toast('报价至少保留一行产品',true);b.closest('.quote-line').remove();renumber()})};$('#add-quote-line').onclick=()=>{$('#quote-line-list').insertAdjacentHTML('beforeend',quoteLine(products,{},$$('#quote-line-list .quote-line').length));renumber()};renumber();$('#modal-submit').onclick=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(d.querySelector('form')).entries());const lines=$$('#quote-line-list .quote-line').map(line=>({productId:line.querySelector('[name=productId]').value||null,description:line.querySelector('[name=description]').value,quantity:Number(line.querySelector('[name=quantity]').value),unitPrice:Number(line.querySelector('[name=unitPrice]').value),unitCost:Number(line.querySelector('[name=unitCost]').value)}));const payload={...data,items:lines,charges:[...(Number(data.extraFeeAmount)>0?[{name:data.extraFeeName||'额外费用',kind:'revenue',amount:Number(data.extraFeeAmount)}]:[]),...(Number(data.costFeeAmount)>0?[{name:data.costFeeName||'预估成本',kind:'cost',amount:Number(data.costFeeAmount)}]:[])]};try{await api(quote?`/api/quotes/${quote.id}`:'/api/quotes',{method:quote?'PUT':'POST',body:JSON.stringify(payload)});d.close();toast(`已保存 ${lines.length} 行报价明细`);load('quotes')}catch(err){toast(err.message,true)}}}

async function renderDashboard(){const d=await api('/api/dashboard');cache.dashboard=d;$('#approval-badge').textContent=d.metrics.pendingApprovals||'';$('#notification-badge').textContent=d.metrics.unreadNotifications||'';const max=Math.max(1,...d.pipeline.map(x=>x.value));return `<div class="hero-strip"><div><p>今日经营脉搏</p><h3>订单有序，资金清楚，风险可见。</h3></div><div class="pulse">● SYSTEM HEALTHY</div></div><div class="metrics"><div class="metric-card"><small>客户资产</small><strong>${d.metrics.customers}</strong><em>客户主档</em></div><div class="metric-card"><small>执行中合同</small><strong>${d.metrics.activeOrders}</strong><em>销售履约</em></div><div class="metric-card"><small>累计确认回款</small><strong>${fmtMoney(d.metrics.revenue)}</strong><em>财务确认口径</em></div><div class="metric-card"><small>现金毛利</small><strong>${fmtMoney(d.metrics.grossCash)}</strong><em>回款－付款－退款</em></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><h3>客户漏斗</h3><span>实时阶段分布</span></div>${d.pipeline.length?`<div class="pipeline">${d.pipeline.map(x=>`<div class="bar-wrap"><div class="bar" style="height:${Math.max(8,x.value/max*100)}%"><b>${x.value}</b></div><small>${statusMap[x.label]||x.label}</small></div>`).join('')}</div>`:empty('还没有客户数据')}</div><div class="panel"><div class="panel-head"><h3>待我关注</h3><span>${d.pending.length} 项</span></div><div class="approval-list">${d.pending.length?d.pending.map(x=>`<div class="approval-item"><strong>${x.document_no}</strong><p>${x.reason} · ${x.requester_name}</p></div>`).join(''):empty('没有待审批事项','当前流程运行顺畅。')}</div></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h3>最近销售合同</h3><span>可追溯至原始报价</span></div>${d.recentOrders.length?table([['合同号',r=>`<span class="docno">${r.document_no}</span>`],['客户','customer_name'],['金额',r=>`<span class="money">${fmtMoney(r.amount,r.currency)}</span>`],['状态',r=>status(r.status)],['创建日期',r=>fmtDate(r.created_at)]],d.recentOrders):empty('还没有销售合同')}</div>`}
async function renderCustomers(){const rows=await api('/api/customers');cache.customers=rows;return pageHead('客户资产库','统一管理客户归属、阶段和下一动作。','<button class="primary" id="add-customer">＋ 新建客户</button>')+smartList('customers',[['客户编号',r=>`<button class="record-link" data-detail="customers" data-id="${r.id}">${r.document_no}</button>`],['客户',r=>`<strong>${esc(r.name)}</strong><br><small class="muted">${esc(r.country)}</small>`],['联系人',r=>`${esc(r.contact_name||'—')}<br><small class="muted">${esc(r.email||r.phone||'')}</small>`],['阶段',r=>status(r.stage)],['等级',r=>`<span class="tag">${r.level}</span>`],['负责人','owner_name'],['下次跟进',r=>fmtDate(r.next_followup_at)]],rows,[['name','客户'],['country','国家'],['stage','阶段',[['new','新线索'],['contacted','已联系'],['qualified','高意向'],['quoted','已报价'],['won','已成交']]],['level','等级',[['A','A级'],['B','B级'],['C','C级']]],['owner_name','负责人']])}
async function renderQuotes(){const rows=await api('/api/quotes');cache.quotes=rows;return pageHead('报价与 PI','多产品报价、版本、成本和预估毛利统一管理。','<button class="primary" id="add-quote">＋ 创建报价</button>')+smartList('quotes',[['PI 编号',r=>`<button class="record-link" data-detail="quotes" data-id="${r.id}">${r.document_no}</button>`],['客户','customer_name'],['金额',r=>`<span class="money">${fmtMoney(r.amount,r.currency)}</span>`],['预估成本',r=>fmtMoney(r.cost,r.currency)],['毛利率',r=>`<strong class="${r.margin_bps<1500?'danger':''}">${(r.margin_bps/100).toFixed(2)}%</strong>`],['状态',r=>status(r.status)],['操作',r=>`<a class="action-link" target="_blank" href="/api/quotes/${r.id}/print">打印 / PDF</a>　${r.status==='draft'?`<button class="action-link" data-submit-quote="${r.id}">提交</button>`:r.status==='effective'?`<button class="action-link" data-convert-quote="${r.id}">转 SO</button>`:'—'}`]],rows,[['document_no','PI 编号'],['customer_name','客户'],['currency','币种',[['USD','USD'],['CNY','CNY'],['EUR','EUR']]],['status','状态',[['draft','草稿'],['approval_pending','审批中'],['effective','已生效'],['rejected','已驳回']]]])}
async function renderOrders(){const rows=await api('/api/orders');cache.orders=rows;return pageHead('销售合同','审批通过后才进入采购、出运、应收和利润核算。','<button class="primary" id="add-order">＋ 直接新建合同</button>',`<a class="secondary" href="/api/export/orders.csv">导出 CSV</a>`)+smartList('orders',[['SO 编号',r=>`<button class="record-link" data-detail="orders" data-id="${r.id}">${r.document_no}</button>`],['客户','customer_name'],['合同金额',r=>`<span class="money">${fmtMoney(r.amount,r.currency)}</span>`],['已收本币',r=>fmtMoney(r.received_base)],['采购','procurement_status'],['出运','delivery_status'],['单据状态',r=>status(r.document_status||r.status)],['履约状态',r=>status(r.status)],['操作',r=>`<a class="action-link" target="_blank" href="/api/orders/${r.id}/print">打印 / PDF</a>　${['draft','rejected'].includes(r.document_status)?`<button class="action-link" data-submit-order="${r.id}">提交生效审批</button>`:'—'}`]],rows,[['document_no','SO 编号'],['customer_name','客户'],['currency','币种',[['USD','USD'],['CNY','CNY'],['EUR','EUR']]],['document_status','单据状态'],['status','履约状态']])}
async function renderProducts(){const rows=await api('/api/products');cache.products=rows;return pageHead('产品中心','销售规格、多供应商报价、复制和批量导入。','<button class="primary" id="add-product">＋ 新建产品</button>',`<a class="secondary" href="/api/products/import-template.csv">下载导入模板</a><button class="secondary" id="import-products">导入 CSV</button>`)+smartList('products',[['产品编号',r=>`<button class="record-link" data-detail="products" data-id="${r.id}">${r.document_no}</button>`],['SKU',r=>`<strong>${esc(r.sku)}</strong>`],['产品名称','name'],['分类','category'],['售价',r=>fmtMoney(r.sale_price,r.currency)],['成本',r=>fmtMoney(r.cost_price,r.currency)],['供应商','supplier_name'],['状态',r=>status(r.status)],['操作',r=>`<button class="action-link" data-copy-product="${r.id}">复制</button>`]],rows,[['sku','SKU'],['name','产品名称'],['category','分类'],['supplier_name','供应商'],['status','状态',[['active','启用'],['inactive','停用']]]])}
async function renderSuppliers(){const rows=await api('/api/suppliers');cache.suppliers=rows;return pageHead('供应商库','准入、风险、合作次数和采购关系集中维护。','<button class="primary" id="add-supplier">＋ 新建供应商</button>')+smartList('suppliers',[['供应商编号',r=>`<button class="record-link" data-detail="suppliers" data-id="${r.id}">${r.document_no}</button>`],['供应商',r=>`<strong>${esc(r.name)}</strong>`],['国家','country'],['联系人','contact_name'],['合作次数',r=>`<strong>${r.cooperation_count||0}</strong>`],['最近合作',r=>fmtDate(r.last_cooperation_at)],['风险',r=>status(r.risk_level)],['状态',r=>status(r.status)]],rows,[['name','供应商'],['country','国家'],['risk_level','风险',[['low','低风险'],['medium','中风险'],['high','高风险']]],['status','准入状态']])}
async function renderPurchases(){const [rows,pending]=await Promise.all([api('/api/purchases'),api('/api/procurement/pending')]);cache.purchases=rows;cache.procurementPending=pending;return pageHead('采购管理','从待采购需求生成 PO，审批通过后形成应付。','<button class="primary" id="add-purchase">＋ 创建采购单</button>')+`<div class="panel pending-pool"><div class="panel-head"><h3>待采购池</h3><span>${pending.length} 条需求</span></div>${table([['销售合同','sales_order_no'],['客户','customer_name'],['产品/物料','description'],['合同数量','ordered_quantity'],['已安排','processed_quantity'],['已关闭','closed_quantity'],['剩余待采购',r=>`<strong>${r.remaining_quantity}</strong>`],['操作',r=>`<button class="action-link danger" data-close-remaining="procurement" data-item="${r.sales_order_item_id}" data-remaining="${r.remaining_quantity}">关闭剩余</button>`]],pending)}</div>`+smartList('purchases',[['PO 编号',r=>`<button class="record-link" data-detail="purchases" data-id="${r.id}">${r.document_no}</button>`],['销售合同',r=>`<span class="docno">${r.sales_order_no}</span>`],['供应商','supplier_name'],['金额',r=>fmtMoney(r.amount,r.currency)],['交期',r=>fmtDate(r.expected_at)],['单据状态',r=>status(r.document_status||r.status)],['采购进度',r=>status(r.status)],['操作',r=>['draft','rejected'].includes(r.document_status)?`<button class="action-link" data-submit-purchase="${r.id}">提交生效审批</button>`:'—']],rows,[['document_no','PO 编号'],['sales_order_no','销售合同'],['supplier_name','供应商'],['document_status','单据状态'],['status','采购进度']])}
async function renderDeliveries(){const [rows,pending]=await Promise.all([api('/api/deliveries'),api('/api/delivery/pending')]);cache.deliveries=rows;cache.deliveryPending=pending;return pageHead('出运管理','从待出运需求生成 DO，审批通过后形成货代应付。','<button class="primary" id="add-delivery">＋ 创建出运单</button>')+`<div class="panel pending-pool"><div class="panel-head"><h3>待出运池</h3><span>${pending.length} 条需求</span></div>${table([['销售合同','sales_order_no'],['客户','customer_name'],['产品/物料','description'],['合同数量','ordered_quantity'],['已安排','processed_quantity'],['已关闭','closed_quantity'],['剩余待出运',r=>`<strong>${r.remaining_quantity}</strong>`],['操作',r=>`<button class="action-link danger" data-close-remaining="delivery" data-item="${r.sales_order_item_id}" data-remaining="${r.remaining_quantity}">关闭剩余</button>`]],pending)}</div>`+smartList('deliveries',[['DO 编号',r=>`<button class="record-link" data-detail="deliveries" data-id="${r.id}">${r.document_no}</button>`],['销售合同',r=>`<span class="docno">${r.sales_order_no}</span>`],['货代','forwarder'],['运输方式','transport_mode'],['追踪号','tracking_no'],['运费',r=>fmtMoney(r.freight,r.currency)],['单据状态',r=>status(r.document_status||r.status)],['物流状态',r=>status(r.status)],['操作',r=>['draft','rejected'].includes(r.document_status)?`<button class="action-link" data-submit-delivery="${r.id}">提交生效审批</button>`:'—']],rows,[['document_no','DO 编号'],['sales_order_no','销售合同'],['forwarder','货代'],['transport_mode','运输方式'],['document_status','单据状态'],['status','物流状态']])}
